declare(strict_types=1);
function h(string $v): string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function mapUrl(array $r): string{$q=trim((string)($r['detected_prefecture']??'').' '.(string)($r['title']??''));$q=preg_replace('/(?:LIVE|Live|live|ライブカメラ|ライブ|24\/7|生中継|定点カメラ)/u',' ',$q)??$q;$q=preg_replace('/\s+/u',' ',$q)??$q;if($q==='')$q='日本';return 'https://www.openstreetmap.org/search?query='.rawurlencode($q);}
function channelUrl(array $r):string{$id=trim((string)($r['channel_id']??''));return $id!==''?'https://www.youtube.com/channel/'.rawurlencode($id):'#';}
function blockDefs():array{return ['hokkaido'=>'北海道','tohoku'=>'東北','kanto'=>'関東','chubu'=>'中部','kinki'=>'近畿','chugoku'=>'中国','shikoku'=>'四国','kyushu'=>'九州','okinawa'=>'沖縄'];}
function loadReviewData(string $path):array{if(!file_exists($path))return []; $x=json_decode((string)@file_get_contents($path),true);return is_array($x)?$x:[];}
function saveReviewData(string $path,array $data):bool{$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT);return $json!==false&&file_put_contents($path,$json,LOCK_EX)!==false;}
function allowedValue(string $value,array $allowed,string $fallback):string{return in_array($value,$allowed,true)?$value:$fallback;}
function containsAnyText(string $text,array $words):bool{$text=mb_strtolower($text,'UTF-8');foreach($words as $w){if(mb_strpos($text,mb_strtolower((string)$w,'UTF-8'))!==false)return true;}return false;}
function flowAssessment(array $r):array{
    $title=(string)($r['title']??'');$desc=(string)($r['description']??'');$channel=(string)($r['channel_title']??'');$text=$title.' '.$desc.' '.$channel;
    $tags=(array)($r['tags']??[]);$score=0;$reasons=[];
    $strong=['駅前','改札','コンコース','駅入口','駅出口','出入口','広場','商店街','繁華街','スクランブル','歩行者','人通り','人流','観光客','参道','門前町','市場','アーケード','shopping street','downtown','pedestrian','plaza'];
    $medium=['駅周辺','駅','交差点','観光地','温泉街','空港','港','ビーチ','公園','street','station','airport','harbor','beach'];
    $weak=['道路','国道','県道','高速','峠','トンネル','河川','ダム','雪道','ski','river','highway'];
    if(containsAnyText($text,$strong)){$score+=8;$reasons[]='人の滞留・通行が見込める語';}
    if(containsAnyText($text,$medium)){$score+=4;$reasons[]='人流観測向きの場所';}
    if(in_array('繁華街',$tags,true)){$score+=6;$reasons[]='繁華街タグ';}
    if(in_array('駅',$tags,true)){$score+=5;$reasons[]='駅タグ';}
    if(in_array('観光',$tags,true)){$score+=3;$reasons[]='観光タグ';}
    if(in_array('道路',$tags,true)&&!array_intersect($tags,['駅','繁華街','観光'])){$score-=3;$reasons[]='道路単独寄り';}
    if(containsAnyText($text,$weak)&&!containsAnyText($text,$strong)&&!array_intersect($tags,['駅','繁華街','観光'])){$score-=3;}
    if(($r['candidate_status']??'')==='除外候補')$score-=10;
    $grade=$score>=11?'◎':($score>=5?'○':'対象外');
    return ['grade'=>$grade,'score'=>$score,'reasons'=>array_values(array_unique($reasons))];
}
function flowTypeAssessment(array $r): array{
    $text=(string)($r['title']??'').' '.(string)($r['description']??'').' '.(string)($r['channel_title']??'');
    $checks=[
        '駅前・出入口'=>['駅前','駅入口','駅出口','出入口','改札','コンコース','station entrance','station square'],
        '繁華街・商店街'=>['繁華街','商店街','アーケード','スクランブル','downtown','shopping street'],
        '観光地・広場'=>['観光地','観光客','広場','参道','門前町','市場','温泉街','plaza','tourist'],
        '交差点・歩道'=>['交差点','歩道','人通り','pedestrian','crossing','street'],
    ];
    foreach($checks as $type=>$words){if(containsAnyText($text,$words))return ['type'=>$type,'confidence'=>'高'];}
    $tags=(array)($r['tags']??[]);
    if(in_array('駅',$tags,true))return ['type'=>'駅周辺','confidence'=>'中'];
    if(in_array('繁華街',$tags,true))return ['type'=>'繁華街・商店街','confidence'=>'中'];
    if(in_array('観光',$tags,true))return ['type'=>'観光地・広場','confidence'=>'中'];
    return ['type'=>'その他','confidence'=>'低'];
}
function pocAssessment(array $r): array{
    $flow=flowAssessment($r);$type=flowTypeAssessment($r);
    $score=(int)($flow['score']??0);
    if(($r['candidate_status']??'')==='採用候補')$score+=3;
    if(($r['site_status']??'未登録')==='未登録')$score+=1;
    if(($r['location_status']??'')==='地域外')$score-=2;
    if(($r['location_status']??'')==='未判定')$score-=1;
    $priority=$score>=15?'A':($score>=10?'B':'C');
    return ['priority'=>$priority,'score'=>$score,'type'=>$type['type'],'type_confidence'=>$type['confidence'],'note'=>'映像内容・利用条件は要確認'];
}
