            'fixed'=>allowedValue((string)($_POST['fixed']??'未確認'),['未確認','◎','○','△','×'],'未確認'),
            'analysis_fit'=>allowedValue((string)($_POST['analysis_fit']??'未確認'),['未確認','◎','○','△','×'],'未確認'),
            'rights'=>allowedValue((string)($_POST['rights']??'未確認'),['未確認','確認済','要許諾'],'未確認'),
            'decision'=>allowedValue((string)($_POST['decision']??'未判定'),['未判定','採用候補','保留','対象外'],'未判定'),
            'memo'=>mb_substr(trim((string)($_POST['memo']??'')),0,500,'UTF-8'),
