    header('Location: national-viewer.php'.($return?'?'.http_build_query($return):''));exit;
}
$status=(string)($_GET['status']??'all');$discovery=(string)($_GET['discovery']??'all');$site=(string)($_GET['site']??'all');$location=(string)($_GET['location']??'all');$tag=(string)($_GET['tag']??'all');$q=trim((string)($_GET['q']??''));$pref=(string)($_GET['pref']??'all');$block=(string)($_GET['block']??'all');$flow=(string)($_GET['flow']??'all');$flowtype=(string)($_GET['flowtype']??'all');$poc=(string)($_GET['poc']??'all');$review=(string)($_GET['review']??'all');
$scopeRows=array_values(array_filter($data,function(array $r)use($block):bool{$rb=(array)($r['search_blocks']??[]);if(!$rb&&!empty($r['search_block']))$rb=[(string)$r['search_block']];return $block==='all'||in_array($block,$rb,true);}));
$rows=array_values(array_filter($scopeRows,function(array $r)use($status,$discovery,$site,$location,$tag,$q,$pref,$flow,$flowtype,$poc,$review,$reviews):bool{if($status!=='all'&&($r['candidate_status']??'')!==$status)return false;if($discovery!=='all'&&($r['discovery_status']??'既知')!==$discovery)return false;if($site!=='all'&&($r['site_status']??'未登録')!==$site)return false;if($location!=='all'&&($r['location_status']??'未判定')!==$location)return false;if($tag!=='all'&&!in_array($tag,$r['tags']??[],true))return false;$det=(string)($r['detected_prefecture']??'');if($pref!=='all'&&$det!==$pref)return false;if($flow!=='all'&&(flowAssessment($r)['grade']??'対象外')!==$flow)return false;if($flowtype!=='all'&&(flowTypeAssessment($r)['type']??'その他')!==$flowtype)return false;if($poc!=='all'&&(pocAssessment($r)['priority']??'C')!==$poc)return false;$rv=$reviews[(string)($r['video_id']??'')]??[];$dec=(string)($rv['decision']??'未判定');if($review==='未審査'&&!empty($rv))return false;if($review==='審査済'&&empty($rv))return false;if(in_array($review,['採用候補','保留','対象外'],true)&&$dec!==$review)return false;if($q!==''){$hay=mb_strtolower(($r['title']??'').' '.($r['channel_title']??'').' '.($r['description']??''),'UTF-8');if(mb_strpos($hay,mb_strtolower($q,'UTF-8'))===false)return false;}return true;}));
$counts=['採用候補'=>0,'要確認'=>0,'除外候補'=>0];$disc=['新規'=>0,'既知'=>0];$sites=['未登録'=>0,'登録済'=>0];$locs=['一致'=>0,'地域外'=>0,'未判定'=>0];$flows=['◎'=>0,'○'=>0,'対象外'=>0];$tagCounts=['道路'=>0,'雪道'=>0,'駅'=>0,'繁華街'=>0,'観光'=>0,'河川'=>0];$flowTypes=['駅前・出入口'=>0,'駅周辺'=>0,'繁華街・商店街'=>0,'観光地・広場'=>0,'交差点・歩道'=>0,'その他'=>0];$pocCounts=['A'=>0,'B'=>0,'C'=>0];$reviewCounts=['未審査'=>0,'審査済'=>0,'採用候補'=>0,'保留'=>0,'対象外'=>0];foreach($scopeRows as $r){$s=$r['candidate_status']??'要確認';if(isset($counts[$s]))$counts[$s]++;$d=$r['discovery_status']??'既知';if(isset($disc[$d]))$disc[$d]++;$ss=$r['site_status']??'未登録';if(isset($sites[$ss]))$sites[$ss]++;$ls=$r['location_status']??'未判定';if(isset($locs[$ls]))$locs[$ls]++;$fg=flowAssessment($r)['grade']??'対象外';if(isset($flows[$fg]))$flows[$fg]++;foreach((array)($r['tags']??[]) as $tg)if(isset($tagCounts[$tg]))$tagCounts[$tg]++;$ft=flowTypeAssessment($r)['type']??'その他';if(isset($flowTypes[$ft]))$flowTypes[$ft]++;$pc=pocAssessment($r)['priority']??'C';if(isset($pocCounts[$pc]))$pocCounts[$pc]++;$rv=$reviews[(string)($r['video_id']??'')]??[];if($rv){$reviewCounts['審査済']++;$dc=(string)($rv['decision']??'未判定');if(isset($reviewCounts[$dc]))$reviewCounts[$dc]++;}else{$reviewCounts['未審査']++;}}
