補','保留','対象外'] as $x):?><option value="<?=h($x)?>" <?=$review===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select><select name="tag"><option value="all">全カテゴリ</option><?php foreach($allTags as $t):?><option value="<?=h($t)?>" <?=$tag===$t?'selected':''?>><?=h($t)?></option><?php endforeach;?></select><button type="submit">絞り込む</button><a href="national-viewer.php" style="padding:9px 8px">リセット</a></form>
