<?php if(!$rows):?><div class="empty">条件に一致する候補はありません。</div><?php else:?><div class="grid"><?php foreach($rows as $r):$s=(string)($r['candidate_status']??'要確認');$rp=(array)($r['searched_prefectures']??[]);$rb=(array)($r['search_blocks']??[]);?><article class="card"><?php if(!empty($r['thumbnail'])):?><img class="thumb" src="<?=h((string)$r['thumbnail'])?>" alt="" loading="lazy"><?php endif;?><div class="body"><div class="status <?=h($s)?>"><?=h($s)?><?php if(($r['site_status']??'未登録')==='未登録'):?> <span class="badge">サイト未登録</span><?php endif;?><?php if(($r['discovery_status']??'既知')==='新規'):?> <span class="badge">API NEW</span><?php endif;?></div><?php $fa=flowAssessment($r);$fg=(string)($fa['grade']??'対象外');$fc=$fg==='◎'?'flowgood':($fg==='○'?'flowmaybe':'flowout');$fta=flowTypeAssessment($r);$pa=pocAssessment($r);?><div class="score">スコア <?=h((string)($r['candidate_score']??0))?> / <span class="badge <?=$fc?>">人流解析 <?=$fg?></span></div><div class="badges"><span class="badge"><?=h((string)($fta['type']??'その他'))?></span><span class="badge">PoC <?=h((string)($pa['priority']??'C'))?></span></div><h2 class="title"><?=h((string)($r['title']??''))?></h2><div class="channel"><?=h((string)($r['channel_title']??''))?></div><div class="badges"><?php foreach(($r['tags']??[]) as $t):?><span class="badge"><?=h((string)$t)?></span><?php endforeach;?><?php if(!empty($r['detected_prefecture'])):?><span class="badge"><?=h((string)$r['detected_prefecture'])?></span><?php endif;?><?php if(($r['location_status']??'')==='地域外'):?><span class="badge warn">地域外</span><?php endif;?></div><?php if($rp):?><div class="score">検索対象: <?=h(implode(' / ',$rp))?></div><?php endif;?><div class="desc"><?=h((string)($r['description']??''))?></div><div class="actions"><a href="<?=h(channelUrl($r))?>" target="_blank" rel="noopener">🏢 発信元</a><a href="<?=h((string)($r['url']??'#'))?>" target="_blank" rel="noopener">▶ 映像ビュー</a><a href="<?=h(mapUrl($r))?>" target="_blank" rel="noopener">地図 ↗</a></div><?php $vid=(string)($r['video_id']??'');$rv=$reviews[$vid]??[];?><form class="reviewbox" method="post"><input type="hidden" name="action" value="save_review"><input type="hidden" name="video_id" value="<?=h($vid)?>"><?php foreach(['block'=>$block,'poc'=>$poc,'flow'=>$flow,'flowtype'=>$flowtype,'status'=>$status,'site'=>$site,'discovery'=>$discovery,'location'=>$location,'pref'=>$pref,'tag'=>$tag,'review'=>$review] as $rk=>$rvv):?><input type="hidden" name="return_<?=h($rk)?>" value="<?=h((string)$rvv)?>"><?php endforeach;?><div class="reviewcurrent"><strong>PoC二次審査</strong><?php if($rv):?> / <?=h((string)($rv['decision']??'未判定'))?> / 更新 <?=h((string)($rv['reviewed_at']??''))?><?php else:?> / 未審査<?php endif;?></div><div class="reviewgrid"><label>映像確認<select name="video_check"><?php foreach(['未確認','確認済'] as $x):?><option value="<?=h($x)?>" <?=($rv['video_check']??'未確認')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label>人物<select name="people"><?php foreach(['未確認','◎','○','△','×'] as $x):?><option value="<?=h($x)?>" <?=($rv['people']??'未確認')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label>定点性<select name="fixed"><?php foreach(['未確認','◎','○','△','×'] as $x):?><option value="<?=h($x)?>" <?=($rv['fixed']??'未確認')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label>解析適性<select name="analysis_fit"><?php foreach(['未確認','◎','○','△','×'] as $x):?><option value="<?=h($x)?>" <?=($rv['analysis_fit']??'未確認')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label>権利確認<select name="rights"><?php foreach(['未確認','確認済','要許諾'] as $x):?><option value="<?=h($x)?>" <?=($rv['rights']??'未確認')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label>PoC判定<select name="decision"><?php foreach(['未判定','採用候補','保留','対象外'] as $x):?><option value="<?=h($x)?>" <?=($rv['decision']??'未判定')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label></div><label style="margin-top:8px">メモ<input type="text" name="memo" maxlength="500" value="<?=h((string)($rv['memo']??''))?>" placeholder="例：歩行者が常時映る、画角固定、配信元確認要"></label><button type="submit">審査結果を保存</button></form></div></article><?php endforeach;?></div><?php endif;?></div></body></html>
